conditional_before_redefine.main.c:
#define PICK 1
int choose(void) {
#if PICK == 1
#undef PICK
#define PICK 2
#endif
 return PICK;
}

defined_before_redefine.main.c:
#define PICK 1
int choose(void) {
#if defined(PICK)
#undef PICK
#define PICK 2
#endif
 return PICK;
}

intervening_nonmatching.main.c:
#define PICK 1
#define OTHER 8
int choose(void) {
#if PICK == 1
#undef PICK
#define PICK 2
#endif
 int x = OTHER;
 return PICK + x;
}

ordinary_references_redefined.main.c:
#define PICK 1
int choose(void) {
 int first = PICK;
#undef PICK
#define PICK 2
 return first + PICK;
}

earlier_function_condition.main.c:
#define PICK 1
int earlier(void) {
#if PICK == 1
#undef PICK
#define PICK 2
#endif
 return 0;
}
int later(void) { return PICK; }
